    "ccipReceive": {
      "notice": "The entrypoint for the CCIP router to call.",
      "details": "Extremely important to ensure only router calls this.The CCIP NatSpec convention states that `ccipReceive` should not revert. We intentionally deviate: reverting on invalid sender/peer data is correct here because accepting and silently discarding a malformed message would lose the bridged tokens with no recovery path. A revert keeps tokens in the CCIP router where they can be retried or recovered.",
      "params": {
        "any2EvmMessage": "The message to process."
      }
    },
